package in.tucor.api.buyer; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="buyer_pickups") public class BuyerPickup {@Id public UUID id;@Column(name="public_id") public String publicId;@Column(name="buyer_id") public UUID buyerId;@Column(name="order_id") public UUID orderId;@Column(name="scheduled_date") public LocalDate scheduledDate;public String status;@Column(name="agent_name") public String agentName;@Column(name="vehicle_number") public String vehicleNumber;@Column(name="volume_confirmed") public Integer volumeConfirmed;public String notes;@Column(name="created_at") public Instant createdAt;@Column(name="updated_at") public Instant updatedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(publicId==null)publicId="PKP-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();if(status==null)status="Pending";createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}}
